// --- src/leaderboard-card.js ---
const BaseCardElement = typeof HTMLElement !== 'undefined' ? HTMLElement : class {};
const PERIOD_CACHE_TTL_MS = 60_000;

class HaLeaderboardCard extends BaseCardElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._rawConfig = {};
    this._config = normalizeConfig({});
    this._hass = null;
    this._lastSignature = null;
    this._activePeriod = this._config.period;
    this._periodCache = new Map();
    this._loadingPeriod = false;
    this._periodRequestSeq = 0;
    this._boundClickHandler = this._onContainerClick.bind(this);
  }

  static getConfigElement() {
    return document.createElement('ha-leaderboard-card-editor');
  }

  static getStubConfig() {
    return {
      type: 'custom:ha-leaderboard-card',
      layout: 'podium',
      limit: 3,
      entities: [],
    };
  }

  setConfig(config) {
    if (!config || typeof config !== 'object') {
      throw new Error('Invalid configuration for ha-leaderboard-card.');
    }
    this._rawConfig = { ...config };
    this._config = normalizeConfig(config);
    this._activePeriod = this._config.period;
    this._periodCache.clear();
    this._lastSignature = null;
    this._render();
    if (this._hass && this._activePeriod !== 'all') {
      this._ensurePeriodData(true);
    }
  }

  set hass(hass) {
    this._hass = hass;
    const signature = this._computeSignature(hass);
    if (signature !== this._lastSignature) {
      this._lastSignature = signature;
      this._render();
    }
    if (this._activePeriod !== 'all') {
      this._ensurePeriodData();
    }
  }

  get hass() {
    return this._hass;
  }

  getCardSize() {
    if (this._config.layout === 'list') {
      return Math.max(2, Math.min(8, this._config.limit + 1));
    }
    if (this._config.layout === 'both') {
      return Math.max(4, Math.min(10, this._config.limit + 3));
    }
    return 4;
  }

  getGridOptions() {
    return {
      columns: 6,
      min_columns: 3,
      rows: this._config.layout === 'both' ? 5 : 4,
      min_rows: 2,
    };
  }

  _getCachedPeriodValues(period) {
    if (period === 'all' || !this._hass) return null;
    const entityIds = collectCandidateEntityIds(this._config, this._hass);
    const cacheKey = `${period}:${entityIds.join(',')}`;
    const cached = this._periodCache.get(cacheKey);
    return cached ? cached.values : null;
  }

  async _ensurePeriodData(force = false) {
    const period = this._activePeriod || this._config.period;
    if (period === 'all' || !this._hass?.states) return;

    const entityIds = collectCandidateEntityIds(this._config, this._hass);
    if (entityIds.length === 0) return;

    const cacheKey = `${period}:${entityIds.join(',')}`;
    const cached = this._periodCache.get(cacheKey);
    const isFresh = cached && Date.now() - cached.timestamp < PERIOD_CACHE_TTL_MS;
    if (!force && isFresh) return;

    const requestSeq = ++this._periodRequestSeq;
    if (!cached) {
      this._loadingPeriod = true;
      this._render();
    }

    try {
      const values = await fetchPeriodValues(this._hass, entityIds, period);
      if (requestSeq !== this._periodRequestSeq) return;
      this._periodCache.set(cacheKey, { timestamp: Date.now(), values });
    } finally {
      if (requestSeq === this._periodRequestSeq) {
        this._loadingPeriod = false;
        this._lastSignature = this._computeSignature(this._hass);
        this._render();
      }
    }
  }

  _computeSignature(hass) {
    if (!hass?.states) return 'no-hass';
    const lang = getLanguage(hass, this._config);
    const activePeriod = this._activePeriod || this._config.period;
    const periodValues = this._getCachedPeriodValues(activePeriod);
    const resolved = resolveEntities(this._config, hass, periodValues);
    const itemSig = resolved.items
      .map((item) => `${item.entityId}:${item.value}:${item.name}:${item.icon}:${item.color}:${item.unit}`)
      .join('|');
    return `${lang}#${activePeriod}#${this._loadingPeriod}#${resolved.totalMatched}#${resolved.totalValue}#${itemSig}`;
  }

  _onContainerClick(event) {
    const periodBtn = event.target.closest('button.period-tab[data-period]');
    if (periodBtn) {
      const nextPeriod = periodBtn.dataset.period;
      if (nextPeriod && nextPeriod !== this._activePeriod) {
        this._activePeriod = nextPeriod;
        this._lastSignature = null;
        this._render();
        if (nextPeriod !== 'all') {
          this._ensurePeriodData();
        }
      }
      return;
    }

    const btn = event.target.closest('button[data-entity-id]');
    if (!btn) return;
    const entityId = btn.dataset.entityId;
    if (!entityId) return;

    this.dispatchEvent(
      new CustomEvent('hass-more-info', {
        detail: { entityId },
        bubbles: true,
        composed: true,
      })
    );
  }

  _getPedestalHeight(item) {
    const pct = item.percentageOfMax || 0;
    if (item.rank === 1) {
      return Math.max(66, Math.round(32 + (pct / 100) * 50));
    }
    if (item.rank === 2) {
      return Math.max(46, Math.min(68, Math.round(26 + (pct / 100) * 44)));
    }
    return Math.max(30, Math.min(54, Math.round(22 + (pct / 100) * 34)));
  }

  _renderPodiumItem(item, config) {
    const customAccentStyle = item.color ? `--custom-accent: ${escapeAttr(item.color)};` : '';
    const pedestalHeight = this._getPedestalHeight(item);
    const rankLabel = `#${item.rank}`;
    const ariaLabel = `${rankLabel} ${item.name}: ${item.formattedValue}${item.unit ? ` ${item.unit}` : ''}`;

    return `
      <button
        type="button"
        class="leaderboard-item podium-item rank-${item.rank}"
        data-entity-id="${escapeAttr(item.entityId)}"
        aria-label="${escapeAttr(ariaLabel)}"
        style="${customAccentStyle}"
      >
        ${item.rank === 1 ? `<span class="podium-crown" aria-hidden="true">${renderIcon('mdi:crown')}</span>` : ''}
        <div class="podium-avatar">
          ${renderIcon(item.icon)}
          <span class="rank-chip" aria-hidden="true">${rankLabel}</span>
        </div>
        <div class="podium-meta">
          <span class="podium-name" title="${escapeAttr(item.name)}">${escapeHtml(item.name)}</span>
          <span class="podium-value">
            <span>${escapeHtml(item.formattedValue)}</span>
            ${item.unit ? `<span class="podium-unit">${escapeHtml(item.unit)}</span>` : ''}
          </span>
          ${config.show_percentage ? `<span class="podium-share">${item.percentageOfTotal}%</span>` : ''}
        </div>
        <div class="podium-pedestal" style="--pedestal-height: ${pedestalHeight}px;" aria-hidden="true">
          ${rankLabel}
        </div>
      </button>
    `;
  }

  _renderListItem(item, config) {
    const customAccentStyle = item.color ? `--custom-accent: ${escapeAttr(item.color)};` : '';
    const ariaLabel = `#${item.rank} ${item.name}: ${item.formattedValue}${item.unit ? ` ${item.unit}` : ''}`;

    return `
      <button
        type="button"
        class="leaderboard-item list-item rank-${item.rank}"
        data-entity-id="${escapeAttr(item.entityId)}"
        aria-label="${escapeAttr(ariaLabel)}"
        style="${customAccentStyle}"
      >
        <span class="list-rank" aria-hidden="true">#${item.rank}</span>
        <span class="list-icon">${renderIcon(item.icon)}</span>
        <span class="list-main">
          <span class="list-name" title="${escapeAttr(item.name)}">${escapeHtml(item.name)}</span>
          <span class="progress-track" aria-hidden="true">
            <span class="progress-fill" style="--bar-width: ${item.percentageOfMax}%;"></span>
          </span>
        </span>
        <span class="list-stats">
          <span class="list-value-row">
            <span>${escapeHtml(item.formattedValue)}</span>
            ${item.unit ? `<span class="list-unit">${escapeHtml(item.unit)}</span>` : ''}
          </span>
          ${config.show_percentage ? `<span class="list-share">${item.percentageOfTotal}%</span>` : ''}
        </span>
      </button>
    `;
  }

  _renderEmptyState(lang) {
    return `
      <div class="empty-state" role="status">
        ${renderIcon(this._config.header_icon || 'mdi:trophy-outline')}
        <p class="empty-state-title">${escapeHtml(localize('card.empty_title', lang))}</p>
        <p class="empty-state-desc">${escapeHtml(localize('card.empty_desc', lang))}</p>
      </div>
    `;
  }

  _renderPeriodSwitcher(config, activePeriod, lang) {
    if (!config.show_period_selector) return '';
    const periods = ['today', 'week', 'month', 'year', 'all'];
    if (
      ['this_week', 'this_month', 'this_year'].includes(config.period) &&
      !periods.includes(config.period)
    ) {
      periods.splice(periods.length - 1, 0, config.period);
    }

    return `
      <div class="period-switcher-row">
        <div class="period-switcher" role="group" aria-label="${escapeAttr(localize('card.period_group_label', lang))}">
          ${periods
            .map((p) => {
              const pressed = p === activePeriod ? 'true' : 'false';
              return `
                <button
                  type="button"
                  class="period-tab"
                  data-period="${escapeAttr(p)}"
                  aria-pressed="${pressed}"
                >${escapeHtml(localize(`card.period_${p}`, lang))}</button>
              `;
            })
            .join('')}
        </div>
        ${this._loadingPeriod ? `<span class="period-loading">${escapeHtml(localize('card.loading_period', lang))}</span>` : ''}
      </div>
    `;
  }

  _render() {
    if (!this.shadowRoot) return;

    const activeEntityId =
      this.shadowRoot.activeElement?.dataset?.entityId || null;
    const activePeriodTab =
      this.shadowRoot.activeElement?.dataset?.period || null;

    const config = this._config;
    const lang = getLanguage(this._hass, config);
    const activePeriod = this._activePeriod || config.period;
    const periodValues = this._getCachedPeriodValues(activePeriod);
    const { items, totalMatched, totalValue } = resolveEntities(config, this._hass, periodValues);

    const hasHeader = Boolean(config.title || config.subtitle || config.header_icon);
    const displayUnit = config.hide_unit
      ? ''
      : config.unit || (items.length > 0 && items.every((i) => i.unit === items[0].unit) ? items[0].unit : '');
    const formattedTotal = Number.isInteger(totalValue)
      ? totalValue.toLocaleString()
      : totalValue.toLocaleString(undefined, { maximumFractionDigits: 1 });

    let bodyHtml = '';
    if (items.length === 0) {
      bodyHtml = this._renderEmptyState(lang);
    } else if (config.layout === 'podium') {
      const podiumItems = items.slice(0, 3);
      const overflowItems = items.slice(3);
      bodyHtml = `
        <div class="podium-grid" data-order="${escapeAttr(config.podium_order)}" data-count="${podiumItems.length}">
          ${podiumItems.map((item) => this._renderPodiumItem(item, config)).join('')}
        </div>
        ${
          overflowItems.length > 0
            ? `
          <div class="section-divider">${escapeHtml(localize('card.runners_up', lang))}</div>
          <div class="ranked-list">
            ${overflowItems.map((item) => this._renderListItem(item, config)).join('')}
          </div>
        `
            : ''
        }
      `;
    } else if (config.layout === 'list') {
      bodyHtml = `
        <div class="ranked-list">
          ${items.map((item) => this._renderListItem(item, config)).join('')}
        </div>
      `;
    } else {
      // layout === 'both'
      const podiumItems = items.slice(0, 3);
      const listItems = items.length > 3 ? items.slice(3) : items;
      const dividerLabel =
        items.length > 3
          ? localize('card.runners_up', lang)
          : localize('card.ranking_breakdown', lang);
      bodyHtml = `
        <div class="podium-grid" data-order="${escapeAttr(config.podium_order)}" data-count="${podiumItems.length}">
          ${podiumItems.map((item) => this._renderPodiumItem(item, config)).join('')}
        </div>
        <div class="section-divider">${escapeHtml(dividerLabel)}</div>
        <div class="ranked-list">
          ${listItems.map((item) => this._renderListItem(item, config)).join('')}
        </div>
      `;
    }

    this.shadowRoot.innerHTML = `
      <style>${CARD_STYLES}</style>
      <ha-card>
        <div class="leaderboard-container">
          ${
            hasHeader
              ? `
            <header class="card-header">
              ${
                config.header_icon
                  ? `<div class="header-icon-wrap">${renderIcon(config.header_icon)}</div>`
                  : ''
              }
              <div class="header-text">
                ${config.title ? `<h2 class="card-title">${escapeHtml(config.title)}</h2>` : ''}
                ${config.subtitle ? `<p class="card-subtitle">${escapeHtml(config.subtitle)}</p>` : ''}
              </div>
              ${
                items.length > 0 && totalMatched > 0
                  ? `<span class="header-total-pill" title="${escapeAttr(localize('card.total_tooltip', lang, { count: totalMatched }))}">${escapeHtml(formattedTotal)}${displayUnit ? ` ${escapeHtml(displayUnit)}` : ''} ${escapeHtml(localize('card.total', lang))}</span>`
                  : ''
              }
            </header>
          `
              : ''
          }
          ${this._renderPeriodSwitcher(config, activePeriod, lang)}
          ${bodyHtml}
        </div>
      </ha-card>
    `;

    const container = this.shadowRoot.querySelector('.leaderboard-container');
    if (container) {
      container.addEventListener('click', this._boundClickHandler);
    }

    if (activeEntityId) {
      const target = this.shadowRoot.querySelector(
        `button[data-entity-id="${CSS.escape(activeEntityId)}"]`
      );
      if (target) target.focus({ preventScroll: true });
    } else if (activePeriodTab) {
      const tabTarget = this.shadowRoot.querySelector(
        `button.period-tab[data-period="${CSS.escape(activePeriodTab)}"]`
      );
      if (tabTarget) tabTarget.focus({ preventScroll: true });
    }
  }
}

// --- src/leaderboard-card-editor.js ---
const BaseEditorElement = typeof HTMLElement !== 'undefined' ? HTMLElement : class {};

class HaLeaderboardCardEditor extends BaseEditorElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._config = {
      type: 'custom:ha-leaderboard-card',
      layout: 'podium',
      podium_order: '2-1-3',
      limit: 3,
      sort_order: 'desc',
      show_percentage: true,
      hide_unit: false,
      hide_zero: false,
      hide_unavailable: true,
      entities: [],
    };
    this._hass = null;
    this._lang = getLanguage(null, this._config);
    this._rendered = false;
  }

  setConfig(config) {
    this._config = {
      type: 'custom:ha-leaderboard-card',
      ...config,
    };
    const nextLang = getLanguage(this._hass, this._config);
    const langChanged = nextLang !== this._lang;
    this._lang = nextLang;

    if (!this._rendered || langChanged) {
      this._render();
    } else {
      this._syncValues();
    }
  }

  set hass(hass) {
    this._hass = hass;
    const nextLang = getLanguage(this._hass, this._config);
    const langChanged = nextLang !== this._lang;
    this._lang = nextLang;

    if (!this._rendered || langChanged) {
      this._render();
    } else {
      this._updateDatalist();
      this._updateMatchBadge();
    }
  }

  _emitConfigChanged(nextConfig) {
    this._config = nextConfig;
    this._updateMatchBadge();
    this.dispatchEvent(
      new CustomEvent('config-changed', {
        detail: { config: nextConfig },
        bubbles: true,
        composed: true,
      })
    );
  }

  _updateField(key, value) {
    const next = { ...this._config };
    if (value === '' || value === undefined || value === null) {
      delete next[key];
    } else {
      next[key] = value;
    }
    this._emitConfigChanged(next);
  }

  _getEntityEntries() {
    const raw = Array.isArray(this._config.entities) ? this._config.entities : [];
    return raw.map((item) =>
      typeof item === 'string'
        ? { entity: item, name: '', icon: '', color: '' }
        : {
            entity: item?.entity || '',
            name: item?.name || '',
            icon: item?.icon || '',
            color: item?.color || '',
          }
    );
  }

  _saveEntityEntries(entries) {
    const cleaned = entries
      .filter((e) => e.entity || e.name || e.icon || e.color)
      .map((e) => {
        const hasOverrides = Boolean(e.name || e.icon || e.color);
        if (!hasOverrides && e.entity) return e.entity;
        const obj = { entity: e.entity };
        if (e.name) obj.name = e.name;
        if (e.icon) obj.icon = e.icon;
        if (e.color) obj.color = e.color;
        return obj;
      });
    this._emitConfigChanged({ ...this._config, entities: cleaned });
  }

  _updateMatchBadge() {
    const badge = this.shadowRoot?.querySelector('#match-badge');
    if (!badge) return;
    const lang = this._lang;
    if (!this._hass?.states) {
      badge.textContent = localize('editor.waiting_hass', lang);
      return;
    }
    const { totalMatched } = resolveEntities(this._config, this._hass);
    badge.textContent =
      totalMatched === 1
        ? localize('editor.matched_one', lang)
        : localize('editor.matched_many', lang, { count: totalMatched });
  }

  _updateDatalist() {
    const datalist = this.shadowRoot?.querySelector('#ha-entity-list');
    if (!datalist || !this._hass?.states) return;
    const ids = Object.keys(this._hass.states).sort();
    datalist.innerHTML = ids
      .map((id) => {
        const name = this._hass.states[id]?.attributes?.friendly_name || '';
        return `<option value="${escapeAttr(id)}">${escapeHtml(name)}</option>`;
      })
      .join('');
  }

  _syncValues() {
    if (!this.shadowRoot) return;
    const norm = normalizeConfig(this._config);
    const setVal = (selector, val) => {
      const el = this.shadowRoot.querySelector(selector);
      if (el && document.activeElement !== el && this.shadowRoot.activeElement !== el) {
        el.value = val ?? '';
      }
    };
    const setChecked = (selector, val) => {
      const el = this.shadowRoot.querySelector(selector);
      if (el) el.checked = Boolean(val);
    };

    setVal('#ed-title', norm.title);
    setVal('#ed-subtitle', norm.subtitle);
    setVal('#ed-header-icon', norm.header_icon);
    setVal('#ed-layout', norm.layout);
    setVal('#ed-podium-order', norm.podium_order);
    setVal('#ed-limit', String(norm.limit));
    setVal('#ed-sort-order', norm.sort_order);
    setVal('#ed-period', norm.period);
    setVal('#ed-unit', norm.unit);
    setVal('#ed-decimals', norm.decimals === null ? '' : String(norm.decimals));
    setVal('#ed-include-pattern', norm.include_pattern);
    setVal('#ed-exclude-pattern', norm.exclude_pattern);
    setVal('#ed-strip-prefix', norm.name_strip_prefix);
    setVal('#ed-strip-suffix', norm.name_strip_suffix);
    setChecked('#ed-show-percentage', norm.show_percentage);
    setChecked('#ed-show-period-selector', norm.show_period_selector);
    setChecked('#ed-hide-unit', norm.hide_unit);
    setChecked('#ed-hide-zero', norm.hide_zero);
    setChecked('#ed-hide-unavailable', norm.hide_unavailable);

    const unitInput = this.shadowRoot.querySelector('#ed-unit');
    if (unitInput) unitInput.disabled = norm.hide_unit;

    this._renderEntityRows();
    this._updateMatchBadge();
  }

  _renderEntityRows() {
    const listEl = this.shadowRoot?.querySelector('#entities-list');
    if (!listEl) return;
    const lang = this._lang;

    const entries = this._getEntityEntries();
    listEl.innerHTML = entries
      .map(
        (entry, idx) => `
      <div class="entity-row" data-index="${idx}">
        <input
          type="text"
          list="ha-entity-list"
          data-field="entity"
          placeholder="${escapeAttr(localize('editor.entity_id_placeholder', lang))}"
          aria-label="Entity ID ${idx + 1}"
          value="${escapeAttr(entry.entity)}"
        />
        <input
          type="text"
          data-field="name"
          placeholder="${escapeAttr(localize('editor.custom_name_placeholder', lang))}"
          aria-label="Custom name ${idx + 1}"
          value="${escapeAttr(entry.name)}"
        />
        <input
          type="text"
          data-field="icon"
          placeholder="${escapeAttr(localize('editor.custom_icon_placeholder', lang))}"
          aria-label="Icon ${idx + 1}"
          value="${escapeAttr(entry.icon)}"
        />
        <div class="color-wrap">
          <input
            type="color"
            data-field="color"
            aria-label="Accent color ${idx + 1}"
            value="${escapeAttr(entry.color || '#f59e0b')}"
          />
        </div>
        <button
          type="button"
          class="btn btn-icon"
          data-remove-index="${idx}"
          aria-label="${escapeAttr(localize('editor.remove', lang))} ${idx + 1}"
          title="${escapeAttr(localize('editor.remove', lang))}"
        >
          ${renderIcon('mdi:delete-outline')}
        </button>
      </div>
    `
      )
      .join('');
  }

  _render() {
    if (!this.shadowRoot) return;
    this._rendered = true;
    const norm = normalizeConfig(this._config);
    const lang = this._lang;
    const t = (key, vars) => localize(key, lang, vars);

    this.shadowRoot.innerHTML = `
      <style>${EDITOR_STYLES}</style>
      <datalist id="ha-entity-list"></datalist>
      <div class="editor-root">
        <section class="editor-section">
          <div class="section-head">
            <h3 class="section-title">${escapeHtml(t('editor.section_header_layout'))}</h3>
          </div>
          <div class="field-grid">
            <div class="field">
              <label for="ed-title">${escapeHtml(t('editor.title'))}</label>
              <input id="ed-title" type="text" value="${escapeAttr(norm.title)}" placeholder="${escapeAttr(t('editor.title_placeholder'))}" />
            </div>
            <div class="field">
              <label for="ed-subtitle">${escapeHtml(t('editor.subtitle'))}</label>
              <input id="ed-subtitle" type="text" value="${escapeAttr(norm.subtitle)}" placeholder="${escapeAttr(t('editor.subtitle_placeholder'))}" />
            </div>
            <div class="field">
              <label for="ed-header-icon">${escapeHtml(t('editor.header_icon'))}</label>
              <input id="ed-header-icon" type="text" value="${escapeAttr(norm.header_icon)}" placeholder="${escapeAttr(t('editor.header_icon_placeholder'))}" />
            </div>
            <div class="field">
              <label for="ed-layout">${escapeHtml(t('editor.layout'))}</label>
              <select id="ed-layout">
                <option value="podium" ${norm.layout === 'podium' ? 'selected' : ''}>${escapeHtml(t('editor.layout_podium'))}</option>
                <option value="list" ${norm.layout === 'list' ? 'selected' : ''}>${escapeHtml(t('editor.layout_list'))}</option>
                <option value="both" ${norm.layout === 'both' ? 'selected' : ''}>${escapeHtml(t('editor.layout_both'))}</option>
              </select>
            </div>
            <div class="field">
              <label for="ed-podium-order">${escapeHtml(t('editor.podium_order'))}</label>
              <select id="ed-podium-order">
                <option value="2-1-3" ${norm.podium_order === '2-1-3' ? 'selected' : ''}>${escapeHtml(t('editor.podium_order_213'))}</option>
                <option value="1-2-3" ${norm.podium_order === '1-2-3' ? 'selected' : ''}>${escapeHtml(t('editor.podium_order_123'))}</option>
              </select>
            </div>
            <div class="field">
              <label for="ed-limit">${escapeHtml(t('editor.limit'))}</label>
              <input id="ed-limit" type="number" min="1" max="50" value="${norm.limit}" />
            </div>
            <div class="field">
              <label for="ed-sort-order">${escapeHtml(t('editor.sort_order'))}</label>
              <select id="ed-sort-order">
                <option value="desc" ${norm.sort_order === 'desc' ? 'selected' : ''}>${escapeHtml(t('editor.sort_desc'))}</option>
                <option value="asc" ${norm.sort_order === 'asc' ? 'selected' : ''}>${escapeHtml(t('editor.sort_asc'))}</option>
              </select>
            </div>
            <div class="field">
              <label for="ed-period">${escapeHtml(t('editor.period'))}</label>
              <select id="ed-period">
                <option value="all" ${norm.period === 'all' ? 'selected' : ''}>${escapeHtml(t('editor.period_all'))}</option>
                <option value="today" ${norm.period === 'today' ? 'selected' : ''}>${escapeHtml(t('editor.period_today'))}</option>
                <option value="week" ${norm.period === 'week' ? 'selected' : ''}>${escapeHtml(t('editor.period_week'))}</option>
                <option value="month" ${norm.period === 'month' ? 'selected' : ''}>${escapeHtml(t('editor.period_month'))}</option>
                <option value="year" ${norm.period === 'year' ? 'selected' : ''}>${escapeHtml(t('editor.period_year'))}</option>
                <option value="this_week" ${norm.period === 'this_week' ? 'selected' : ''}>${escapeHtml(t('editor.period_this_week'))}</option>
                <option value="this_month" ${norm.period === 'this_month' ? 'selected' : ''}>${escapeHtml(t('editor.period_this_month'))}</option>
                <option value="this_year" ${norm.period === 'this_year' ? 'selected' : ''}>${escapeHtml(t('editor.period_this_year'))}</option>
              </select>
            </div>
            <div class="field">
              <label for="ed-unit">${escapeHtml(t('editor.unit'))}</label>
              <input id="ed-unit" type="text" value="${escapeAttr(norm.unit)}" placeholder="${escapeAttr(t('editor.unit_placeholder'))}" ${norm.hide_unit ? 'disabled' : ''} />
            </div>
            <div class="field">
              <label for="ed-decimals">${escapeHtml(t('editor.decimals'))}</label>
              <input id="ed-decimals" type="number" min="0" max="6" value="${norm.decimals === null ? '' : norm.decimals}" placeholder="${escapeAttr(t('editor.decimals_placeholder'))}" />
            </div>
          </div>
          <div class="toggle-row">
            <label class="toggle-label">
              <input id="ed-show-percentage" type="checkbox" ${norm.show_percentage ? 'checked' : ''} />
              ${escapeHtml(t('editor.show_percentage'))}
            </label>
            <label class="toggle-label">
              <input id="ed-show-period-selector" type="checkbox" ${norm.show_period_selector ? 'checked' : ''} />
              ${escapeHtml(t('editor.show_period_selector'))}
            </label>
            <label class="toggle-label">
              <input id="ed-hide-unit" type="checkbox" ${norm.hide_unit ? 'checked' : ''} />
              ${escapeHtml(t('editor.hide_unit'))}
            </label>
            <label class="toggle-label">
              <input id="ed-hide-zero" type="checkbox" ${norm.hide_zero ? 'checked' : ''} />
              ${escapeHtml(t('editor.hide_zero'))}
            </label>
            <label class="toggle-label">
              <input id="ed-hide-unavailable" type="checkbox" ${norm.hide_unavailable ? 'checked' : ''} />
              ${escapeHtml(t('editor.hide_unavailable'))}
            </label>
          </div>
        </section>

        <section class="editor-section">
          <div class="section-head">
            <h3 class="section-title">${escapeHtml(t('editor.section_filter'))}</h3>
            <span id="match-badge" class="match-badge"></span>
          </div>
          <div class="field-grid">
            <div class="field">
              <label for="ed-include-pattern">${escapeHtml(t('editor.include_pattern'))}</label>
              <input id="ed-include-pattern" type="text" value="${escapeAttr(norm.include_pattern)}" placeholder="${escapeAttr(t('editor.include_placeholder'))}" />
              <span class="hint">${escapeHtml(t('editor.include_hint'))}</span>
            </div>
            <div class="field">
              <label for="ed-exclude-pattern">${escapeHtml(t('editor.exclude_pattern'))}</label>
              <input id="ed-exclude-pattern" type="text" value="${escapeAttr(norm.exclude_pattern)}" placeholder="${escapeAttr(t('editor.exclude_placeholder'))}" />
              <span class="hint">${escapeHtml(t('editor.exclude_hint'))}</span>
            </div>
            <div class="field">
              <label for="ed-strip-prefix">${escapeHtml(t('editor.strip_prefix'))}</label>
              <input id="ed-strip-prefix" type="text" value="${escapeAttr(norm.name_strip_prefix)}" placeholder="${escapeAttr(t('editor.strip_prefix_placeholder'))}" />
            </div>
            <div class="field">
              <label for="ed-strip-suffix">${escapeHtml(t('editor.strip_suffix'))}</label>
              <input id="ed-strip-suffix" type="text" value="${escapeAttr(norm.name_strip_suffix)}" placeholder="${escapeAttr(t('editor.strip_suffix_placeholder'))}" />
            </div>
          </div>
        </section>

        <section class="editor-section">
          <div class="section-head">
            <h3 class="section-title">${escapeHtml(t('editor.section_entities'))}</h3>
            <button type="button" class="btn" id="add-entity-btn">
              ${renderIcon('mdi:plus')}
              ${escapeHtml(t('editor.add_entity'))}
            </button>
          </div>
          <span class="hint">${escapeHtml(t('editor.entities_hint'))}</span>
          <div id="entities-list" class="entities-list"></div>
        </section>
      </div>
    `;

    this._renderEntityRows();
    this._updateDatalist();
    this._updateMatchBadge();
    this._bindEvents();
  }

  _bindEvents() {
    const root = this.shadowRoot;
    if (!root) return;

    const bindInput = (selector, key, transform = (v) => v) => {
      const el = root.querySelector(selector);
      if (!el) return;
      el.addEventListener('input', (e) => {
        this._updateField(key, transform(e.target.value));
      });
    };

    const bindSelect = (selector, key, transform = (v) => v) => {
      const el = root.querySelector(selector);
      if (!el) return;
      el.addEventListener('change', (e) => {
        this._updateField(key, transform(e.target.value));
      });
    };

    const bindCheck = (selector, key, onToggle) => {
      const el = root.querySelector(selector);
      if (!el) return;
      el.addEventListener('change', (e) => {
        if (onToggle) onToggle(e.target.checked);
        this._updateField(key, e.target.checked);
      });
    };

    bindInput('#ed-title', 'title');
    bindInput('#ed-subtitle', 'subtitle');
    bindInput('#ed-header-icon', 'header_icon');
    bindSelect('#ed-layout', 'layout');
    bindSelect('#ed-podium-order', 'podium_order');
    bindInput('#ed-limit', 'limit', (v) => (v === '' ? undefined : Number(v)));
    bindSelect('#ed-sort-order', 'sort_order');
    bindSelect('#ed-period', 'period');
    bindInput('#ed-unit', 'unit');
    bindInput('#ed-decimals', 'decimals', (v) => (v === '' ? undefined : Number(v)));
    bindInput('#ed-include-pattern', 'include_pattern');
    bindInput('#ed-exclude-pattern', 'exclude_pattern');
    bindInput('#ed-strip-prefix', 'name_strip_prefix');
    bindInput('#ed-strip-suffix', 'name_strip_suffix');

    bindCheck('#ed-show-percentage', 'show_percentage');
    bindCheck('#ed-show-period-selector', 'show_period_selector');
    bindCheck('#ed-hide-unit', 'hide_unit', (checked) => {
      const unitInput = root.querySelector('#ed-unit');
      if (unitInput) unitInput.disabled = checked;
    });
    bindCheck('#ed-hide-zero', 'hide_zero');
    bindCheck('#ed-hide-unavailable', 'hide_unavailable');

    root.querySelector('#add-entity-btn')?.addEventListener('click', () => {
      const entries = this._getEntityEntries();
      entries.push({ entity: '', name: '', icon: '', color: '' });
      const nextRaw = entries.map((e) =>
        e.name || e.icon || e.color ? e : e.entity
      );
      this._config = { ...this._config, entities: nextRaw };
      this._renderEntityRows();
    });

    const listEl = root.querySelector('#entities-list');
    listEl?.addEventListener('input', (e) => {
      const row = e.target.closest('.entity-row');
      if (!row) return;
      const idx = Number(row.dataset.index);
      const field = e.target.dataset.field;
      if (!Number.isInteger(idx) || !field) return;

      const entries = this._getEntityEntries();
      if (!entries[idx]) return;
      entries[idx] = { ...entries[idx], [field]: e.target.value };
      this._saveEntityEntries(entries);
    });

    listEl?.addEventListener('click', (e) => {
      const btn = e.target.closest('button[data-remove-index]');
      if (!btn) return;
      const idx = Number(btn.dataset.removeIndex);
      if (!Number.isInteger(idx)) return;
      const entries = this._getEntityEntries();
      entries.splice(idx, 1);
      this._saveEntityEntries(entries);
      this._renderEntityRows();
    });
  }
}

// --- src/index.js ---
if (typeof customElements !== 'undefined') {
  if (!customElements.get('ha-leaderboard-card')) {
    customElements.define('ha-leaderboard-card', HaLeaderboardCard);
  }
  if (!customElements.get('ha-leaderboard-card-editor')) {
    customElements.define('ha-leaderboard-card-editor', HaLeaderboardCardEditor);
  }
}

if (typeof window !== 'undefined') {
  window.customCards = window.customCards || [];
  if (!window.customCards.some((c) => c.type === 'ha-leaderboard-card')) {
    window.customCards.push({
      type: 'ha-leaderboard-card',
      name: 'Leaderboard Card',
      description:
        'Rank and showcase your top entities in a podium or ranked progress bar view.',
      preview: false,
      documentationURL: 'https://github.com/nicolasjweber/ha-leaderboard-card',
    });
  }
}

export {
  HaLeaderboardCard,
  HaLeaderboardCardEditor,
  calculateDeltaFromHistory,
  calculateDeltaFromStatBuckets,
  collectCandidateEntityIds,
  computePeriodBounds,
  fetchPeriodValues,
  globToRegExp,
  normalizeConfig,
  normalizePeriod,
  resolveEntities,
  getLanguage,
  localize,
};
